import{_ as t,o,c as a,a2 as n}from"./chunks/framework.DGk0zlJw.js";const u=JSON.parse('{"title":"Component library as-built (Phase 2 as-built)","description":"","frontmatter":{},"headers":[],"relativePath":"design/redesign-2026-10-16-组件库落地.md","filePath":"design/redesign-2026-10-16-组件库落地.md"}'),d={name:"design/redesign-2026-10-16-组件库落地.md"};function r(i,e,s,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="component-library-as-built-phase-2-as-built" tabindex="-1">Component library as-built (Phase 2 as-built) <a class="header-anchor" href="#component-library-as-built-phase-2-as-built" aria-label="Permalink to &quot;Component library as-built (Phase 2 as-built)&quot;">​</a></h1><blockquote><p>2026-10-16. Where the redesign-plan §5 component library actually landed in the repo. The design draft is external input; this document records <strong>the in-repo facts that have already landed</strong>: the single token source, the component factory inventory, the consolidated surface, and the not-yet-consolidated remainder. For the vocabulary and the contract see <code>redesign-2026-10-16-契约.md</code> (widget side).</p></blockquote><h2 id="_1-token-system-single-source-and-delegation" tabindex="-1">1 Token system (single source and delegation) <a class="header-anchor" href="#_1-token-system-single-source-and-delegation" aria-label="Permalink to &quot;1 Token system (single source and delegation)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Single source</th><th>Placement</th></tr></thead><tbody><tr><td>Font size / corner radius / spacing</td><td><code>src/Beacon.App/Services/DesignTokens.cs</code></td><td>8 font sizes + 6 corner radii + spacing scale; the only source on the App-side C# surface</td></tr><tr><td>Corner radius (XAML surface)</td><td><code>src/Beacon.App/App.xaml</code> resource mirror</td><td>WinUI 3 has no <code>x:Static</code>, so XAML can only use <code>StaticResource</code>; <strong>the C# and XAML copies must be changed in sync</strong> (both sides carry sync-warning comments)</td></tr><tr><td>Color / severity colors</td><td><code>UiPalette</code> (App) + <code>PaletteResolver</code>/<code>HighContrastPalette</code> (Core)</td><td>Component factories never hold color; brushes are resolved by the caller and passed in</td></tr><tr><td>Base foreground/background</td><td><code>ThemeColors</code> (App.Windows)</td><td>Progress-bar track base color and the like are derived via <code>Opacity</code></td></tr><tr><td>Motion</td><td><code>MotionEngine</code> (App)</td><td>Single source for durations/easing; components do not embed animation constants</td></tr><tr><td>Size / DPI</td><td><code>DpiLayoutMath</code> (Core)</td><td>DIP→px conversion happens exactly once at the Win32 boundary (same convention in all four windows)</td></tr><tr><td>Progress tiers</td><td><code>ProgressTiers</code> (Core, 0.8/0.98 thresholds)</td><td>PinnedHost <code>BarFillColor</code> delegates to it; the App no longer holds the thresholds</td></tr></tbody></table><p>Value-equivalence discipline: consolidation is always <strong>zero value change</strong> (anchored by the CI S/O/Q/F5/G pixel assertions); off-scale literals like <code>3</code> (detail-table row spacing, chip top/bottom spacing) are brought into components at their original values with comments — visuals are never changed as a side effect of consolidation.</p><h2 id="_2-component-factory-inventory-src-beacon-app-components" tabindex="-1">2 Component factory inventory (<code>src/Beacon.App/Components/</code>) <a class="header-anchor" href="#_2-component-factory-inventory-src-beacon-app-components" aria-label="Permalink to &quot;2 Component factory inventory (`src/Beacon.App/Components/`)&quot;">​</a></h2><p>Conventions: <code>internal static class</code> factories; components hold typography/geometry (via DesignTokens) and <strong>never hold color</strong> (brushes come from the caller); conditional children are always added imperatively via <code>Add</code> (a null inside a collection initializer blows up at runtime).</p><table tabindex="0"><thead><tr><th>Factory</th><th>Pieces</th><th>Adopted by (in-repo facts)</th></tr></thead><tbody><tr><td>ComponentText</td><td>Caption / Body</td><td>QuickPanel status rows/event rows (a517594)</td></tr><tr><td>ComponentIcon</td><td>StatusDot</td><td>QuickPanel row-leading light</td></tr><tr><td>ComponentSurface</td><td>Card</td><td>Vocabulary piece (settings card face follows the same convention)</td></tr><tr><td>ComponentBadge</td><td>Count</td><td>Vocabulary piece</td></tr><tr><td>ComponentDivider</td><td>Horizontal</td><td>Vocabulary piece</td></tr><tr><td>ComponentStatus</td><td>Indicator / OfflineHollow</td><td>DetailWindow header light (bf95dde); the hollow variant = the capsule offline-banner convention</td></tr><tr><td>ComponentMetric</td><td>Value</td><td>Vocabulary piece (waiting on Phase 3 binding)</td></tr><tr><td>ComponentProgress</td><td>FillColor / Bar</td><td>FillColor delegates to ProgressTiers; Bar is a static-bar vocabulary piece</td></tr><tr><td>ComponentKeyValue</td><td>Row</td><td>DetailWindow detail table (1db70de)</td></tr><tr><td>ComponentList</td><td>Vertical</td><td>DetailWindow detail table container</td></tr><tr><td>ComponentCard</td><td>Status</td><td>Vocabulary piece (a Surface.Card composition)</td></tr><tr><td>ComponentAction</td><td>Button / Item / Menu / Link</td><td>Detail action area + QuickPanel pin context menu (bb86927); Link is a vocabulary piece</td></tr><tr><td>ComponentLayout</td><td>Row / Column / Columns / SectionLabel / When</td><td>QuickPanel&#39;s three rows and empty-section collapse, Detail header row/action row/section labels, PinnedHost six columns (8caf0b5)</td></tr><tr><td>ComponentFeedback</td><td>Empty / Loading / Error / Offline</td><td>Vocabulary piece (5489352); the current UX convention = empty-section hiding + XAML banners</td></tr></tbody></table><h2 id="_3-not-yet-consolidated-remainder-advanced-surface-by-surface-does-not-block-the-phase" tabindex="-1">3 Not-yet-consolidated remainder (advanced surface by surface; does not block the phase) <a class="header-anchor" href="#_3-not-yet-consolidated-remainder-advanced-surface-by-surface-does-not-block-the-phase" aria-label="Permalink to &quot;3 Not-yet-consolidated remainder (advanced surface by surface; does not block the phase)&quot;">​</a></h2><ul><li>Bespoke Thickness: chip <code>Padding(8,3,8,3)</code>, capsule/panel XAML padding — handled along the way when the corresponding surfaces get componentized.</li><li>The SettingsWindow button family (about 17 <code>new Button</code> sites): form buttons, not 「动作」 (action) vocabulary; waiting for the form-componentization batch.</li><li>XAML-surface layout (QuickPanelWindow.xaml&#39;s Grid/Stack): XAML has no factory to land in; the resource-mirror constraint stays.</li></ul><h2 id="_4-proof-surface" tabindex="-1">4 Proof surface <a class="header-anchor" href="#_4-proof-surface" aria-label="Permalink to &quot;4 Proof surface&quot;">​</a></h2><p>The proof for adopted pieces = CI pixel assertions (green as long as value equivalence holds). The proof surface for the vocabulary pieces (Surface/Badge/Divider/Metric/StatusCard/ Link/Column/Feedback four states) = the <strong>independent visual example page</strong> at the end of Phase 2 (todo phasing row 9) and the Phase 3 binding engine; landing with no adopting surface is the by-design vocabulary stage, not a finished state.</p>',12)])])}const b=t(d,[["render",r]]);export{u as __pageData,b as default};
